def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]

    # Count consecutive opponent defections at the tail
    tail_def = 0
    for a in reversed(opp):
        if a == 'D':
            tail_def += 1
        else:
            break

    # Count consecutive opponent cooperations at the tail
    tail_coop = 0
    for a in reversed(opp):
        if a == 'C':
            tail_coop += 1
        else:
            break

    opp_coop = sum(1 for a in opp if a == 'C')
    opp_def = n - opp_coop
    coop_rate = opp_coop / n

    recent_len = min(10, n)
    recent = opp[-recent_len:]
    recent_coop = sum(1 for a in recent if a == 'C')

    # If opponent is persistently defecting for a long stretch, stop wasting C
    if tail_def >= 4:
        # Rare probe to potentially reset to cooperation (matters for four_D_ALLC style)
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # If opponent has just defected a few times, retaliate but be ready to forgive
    if tail_def >= 1:
        # Against very cooperative opponents, forgive quickly to maintain mutual C
        if coop_rate > 0.7 and tail_def <= 2:
            # single-round retaliation then back to C
            if tail_def == 1 and rng.random() < 0.85:
                return 'D'
            return 'C'
        # For less cooperative opponents, hit back harder
        if coop_rate > 0.5:
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        # Mostly-defecting opponents: defect
        return 'D'

    # Opponent cooperated last round
    # Highly cooperative opponent: mostly cooperate, occasional probe
    if coop_rate > 0.8:
        # Don't probe too aggressively or we lose mutual C
        if recent_coop == recent_len:
            # only rare probes to test
            if n % 25 == 0 and n > 0:
                return 'D'
            return 'C'
        return 'C'

    # Moderately cooperative opponent
    if coop_rate > 0.5:
        # If our own last move was D and they cooperated (we got exploited), just C now
        if my[-1] == 'D':
            return 'C'
        # Occasionally probe
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Mostly-defecting opponent who just cooperated: try to reward
    if coop_rate > 0.3:
        if rng.random() < 0.7:
            return 'C'
        return 'D'

    # Mostly-defecting overall, but recently cooperated: cautiously cooperate,
    # but do not fully trust — probe with occasional defection
    if tail_coop >= 1:
        if rng.random() < 0.7:
            return 'C'
        return 'D'

    return 'D'
